<script setup lang="ts">
/**
 * A score as a row of marks (`design/components/rating.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rating.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef } from 'vue'

import { Icon, agentMember, ratingModel, ratingPress, roveRating } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/rating.module.css'

export type RatingSize = NonNullable<RatingProps['size']>

export interface RatingMessages {
  /** A mark's name, from the value it sets and that value's numeral: "3 stars". */
  mark: (value: number, numeral: string) => string
  /** The shown rating's name, one sentence: "Rating: 4.3 out of 5". */
  shown: (label: string, value: string, max: string) => string
}

export interface RatingProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField, which names the group with its label.
   */
  ariaLabelledby?: string
  /**
   * A required rating cannot be cleared by a press.
   */
  ariaRequired?: boolean
  defaultValue?: number | null
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * The rating's name. A control's group is named by it ("Rate this answer") unless a FormField
   * names it, and a shown rating's sentence starts with it ("Average rating").
   */
  label: string
  /**
   * Writes the numerals of the marks' names and the shown sentence. Defaults to the page's own.
   */
  locale?: string
  /**
   * The number of marks: a whole number from 2 to 10. Default 5.
   */
  max?: number
  messages?: RatingMessages
  /**
   * Posts the value as a whole number, or nothing when the rating holds none.
   */
  name?: string
  /**
   * Shows the rating as an image a reader reads and cannot change.
   */
  readOnly?: boolean
  /**
   * The marks' size: the icon sizes. A control's hit targets stay one size.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * What the rating holds. A control holds a whole number from 1 to `max`, or `null` for no
   * rating. A shown rating holds any value from 0 to `max`, drawn to one decimal place.
   */
  value?: number | null
}

defineOptions({ name: 'Rating', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<RatingProps>(), {
  ariaRequired: undefined,
  disabled: false,
  invalid: false,
  readOnly: false,
  size: 'md',
})
const emit = defineEmits<{ change: [value: number | null] }>()
const mirror = ref(props.defaultValue ?? null)
const root = useTemplateRef<HTMLElement>('root')
const model = computed(() =>
  ratingModel({
    value: props.value === undefined ? mirror.value : props.value,
    label: props.label,
    max: props.max,
    readOnly: props.readOnly,
    locale: props.locale,
    messages: props.messages,
  }),
)
const settle = computed(
  () => (next: number | null) =>
    next !== model.value.value && ((mirror.value = next), emit('change', next), true),
)
const stop = computed(() => model.value.value ?? 1)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Rating',
    element: () => root.value,
    state: () => ({
      value: model.value.value,
      max: model.value.max,
      readonly: props.readOnly,
      disabled: props.disabled,
      invalid: props.invalid,
    }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (props.readOnly) throw new Error('The rating is shown and takes no press.')
            if (!Number.isInteger(value) || value < 1 || value > model.value.max) {
              throw new Error(`A rating is a whole number from 1 to ${model.value.max}.`)
            }
            settle.value(value)
          })(),
      },
      clear: () =>
        (() => {
          if (props.readOnly) throw new Error('The rating is shown and takes no press.')
          if (props.ariaRequired === true) throw new Error('A required rating keeps its mark.')
          settle.value(null)
        })(),
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <span
    v-if="readOnly"
    ref="root"
    :class="styles.rating"
    :id="id"
    role="img"
    :aria-label="model.sentence"
    :aria-describedby="ariaDescribedby"
    :data-size="size"
    data-readonly=""
    data-member="rating"
  >
    <template v-for="mark in model.marks" :key="mark.value">
      <!-- mark -->
      <span :class="styles.mark" :data-fill="mark.fill">
        <span :class="styles.glyph">
          <Icon name="rating" :size="size" />
          <span :class="styles.fill" :style="{ inlineSize: mark.share }">
            <Icon name="rating" :size="size" />
          </span>
        </span>
      </span>
    </template>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="model.value === null ? '' : String(model.value)"
      :disabled="disabled && !readOnly"
    />
  </span>
  <span
    v-else
    ref="root"
    :class="styles.rating"
    :id="id"
    role="radiogroup"
    :aria-label="label"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-required="ariaRequired === true ? true : undefined"
    :aria-invalid="invalid ? true : undefined"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    data-member="rating"
  >
    <template v-for="mark in model.marks" :key="mark.value">
      <!-- mark -->
      <button
        :class="styles.mark"
        type="button"
        role="radio"
        :aria-checked="mark.value === model.value"
        :aria-label="mark.name"
        :disabled="disabled"
        :tabindex="mark.value === stop ? 0 : -1"
        :data-fill="mark.fill"
        @click="settle(ratingPress(mark.value, model.value, ariaRequired === true))"
        @keydown="roveRating($event, settle)"
      >
        <span :class="styles.glyph">
          <Icon name="rating" :size="size" />
          <span :class="styles.fill" :style="{ inlineSize: mark.share }">
            <Icon name="rating" :size="size" />
          </span>
        </span>
      </button>
    </template>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="model.value === null ? '' : String(model.value)"
      :disabled="disabled && !readOnly"
    />
  </span>
</template>
